{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 2,
      "verse": 5,
      "text_ar": "وكل رجل صنع إلهه وسجد له، فترك بني البشر الرب طوال أيام أونوش وذريةه؛ فأُشتعل غضب الرب بسبب أعمالهم وفجائرهم التي ارتكبوها على الأرض."
    },
    {
      "chapter": 2,
      "verse": 6,
      "text_ar": "فأغرق الرب مياه نهر جيهون عليهم، فأهلكهم واستهلكهم، فدمر الجزء الثالث من الأرض، ومع ذلك لم يتراجع بني البشر عن طرقهم الشريرة، وظلت أيديهم تمتد للشر في وجه الرب."
    },
    {
      "chapter": 2,
      "verse": 7,
      "text_ar": "وفي ذلك الوقت لم يكن هناك زرع ولا حصاد في الأرض؛ فلم يكن طعام لبنِي البشر وكان المجاعة شديدة جدًا في ذلك."
    },
    {
      "chapter": 2,
      "verse": 8,
      "text_ar": "وأصبح البذور التي زرعوها في ذلك الوقت شوكًا وشوكًا وسنامًا؛ لأن هذا الإعلان عن الأرض منذ أيام آدم كان من لعنة الله، الذي لعن الأرض بسبب الخطيئة التي ارتكبها آدم أمام الرب."
    },
    {
      "chapter": 2,
      "verse": 9,
      "text_ar": "وعندما استمر الناس في تمردهم وتجاوزهم لله، وإفساد طرقهم، صارت الأرض هي الأخرى فاسدة."
    },
    {
      "chapter": 2,
      "verse": 10,
      "text_ar": "وعاش أونوش تسعين سنة وأنجب قايين."
    },
    {
      "chapter": 2,
      "verse": 11,
      "text_ar": "فنشر قايين وهو في الأربعين من عمره، فأصبح حكيماً وعنده معرفة ومهارة في كل حكمة، وساد جميع بني البشر، وقادهم إلى الحكمة والعلم؛ لأن قايين كان رجلاً حكيمًا جدًا ويفهم كل حكمة، وبحكمته كان يملك على الأرواح والجن."
    },
    {
      "chapter": 2,
      "verse": 12,
      "text_ar": "وعلم قايين بحكمته أن الله سيهلك بني البشر لأنهم أخطأوا على الأرض، وأن الرب في الأيام الأخيرة سيجلب عليهم مياه الفيضان."
    },
    {
      "chapter": 2,
      "verse": 13,
      "text_ar": "وفي ذلك الوقت كتب قايين على ألواح حجرية ما سيحدث في المستقبل، ووضعها في كنوزه."
    },
    {
      "chapter": 2,
      "verse": 14,
      "text_ar": "وساد قايين على كل الأرض، وحوّل بعض بني البشر إلى خدمة الله."
    }
  ]
}
